import{_ as r,a0 as l,w as d,s as u,ao as p,I as o,x as i,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Pidgin：Skype for Business 的開源替代品 | LCTT x X-CMD","titleTemplate":false,"description":"Pidgin：Skype for Business 的開源替代品 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Pidgin：Skype for Business 的開源替代品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Pidgin：Skype for Business 的開源替代品 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180426 Get started with Pidgin- An open source replacement for Skype for Business","title":"Pidgin：Skype for Business 的開源替代品","tag":"201806","desc":""},"relativePath":"201806/20180426 Get started with Pidgin- An open source replacement for Skype for Business.md","filePath":"[post].md"}'),a={name:"201806/20180426 Get started with Pidgin- An open source replacement for Skype for Business.md"};function f(g,e,m,P,k,y){const s=l("Link");return d(),u("div",null,[e[29]||(e[29]=p('<h1 id="pidgin-skype-for-business-的開源替代品" tabindex="-1">Pidgin：Skype for Business 的開源替代品 <a class="header-anchor" href="#pidgin-skype-for-business-的開源替代品" aria-label="Permalink to “Pidgin：Skype for Business 的開源替代品”">​</a></h1><blockquote><p>用可以和 Office 365 協同工作的開源軟件換下你的專有化的溝通軟件。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/meeting-team-listen-communicate.png?itok=KEBP6vZ_" alt=""></p><p>技術正處在一個有趣的十字路口，Linux 統治服務器領域，但微軟統治企業桌面。 Office 365、Skype for Business、Microsoft Teams、OneDrive、Outlook ......等等，這些是支配企業工作空間的是微軟軟件和服務。</p><p>如果你可以使用自由和開源程序替換該專有軟件，並使其與你別無選擇，但只能使用的 Office 365 的後端一起工作？是的，因為這正是我們要用 Pidgin 做的，它是 Skype 的開源替代品。</p><h3 id="安裝-pidgin-和-sipe" tabindex="-1">安裝 Pidgin 和 SIPE <a class="header-anchor" href="#安裝-pidgin-和-sipe" aria-label="Permalink to “安裝 Pidgin 和 SIPE”">​</a></h3>',6)),o("p",null,[e[2]||(e[2]=i("微軟的 Office Communicator 變成了 Microsoft Lync，它成為我們今天所知的 Skype for Business。現在有針對 Linux 的",-1)),t(s,{href:"https://tel.red/linux.php"},{default:n(()=>[...e[0]||(e[0]=[i("付費軟件",-1)])]),_:1}),e[3]||(e[3]=i("提供了與 Skype for Business 相同的功能，但 ",-1)),t(s,{href:"https://pidgin.im/"},{default:n(()=>[...e[1]||(e[1]=[i("Pidgin",-1)])]),_:1}),e[4]||(e[4]=i(" 是 GNU GPL 授權的、完全自由開源的選擇。",-1))]),e[30]||(e[30]=o("p",null,"Pidgin 可以在幾乎每個 Linux 發行版的倉庫中找到，因此，使用它不應該是一個問題。唯一不能在 Pidgin 中使用的 Skype 功能是屏幕共享，並且文件共享可能會失敗，但有辦法解決這個問題。",-1)),o("p",null,[e[6]||(e[6]=i("你還需要一個 ",-1)),t(s,{href:"http://sipe.sourceforge.net/"},{default:n(()=>[...e[5]||(e[5]=[i("SIPE",-1)])]),_:1}),e[7]||(e[7]=i(" 插件，因為它是使 Pidgin 成為 Skype for Business 替代品的秘密武器的一部分。請注意，",-1)),e[8]||(e[8]=o("code",null,"sipe",-1)),e[9]||(e[9]=i(" 庫在不同的發行版中有不同的名稱。例如，庫在 System76 的 Pop_OS! 中是 ",-1)),e[10]||(e[10]=o("code",null,"pidgin-sipe",-1)),e[11]||(e[11]=i("，而在 Solus 3 倉庫中是 ",-1)),e[12]||(e[12]=o("code",null,"sipe",-1)),e[13]||(e[13]=i("。",-1))]),e[31]||(e[31]=p('<p>滿足了先決條件，你可以開始配置 Pidgin。</p><h3 id="配置-pidgin" tabindex="-1">配置 Pidgin <a class="header-anchor" href="#配置-pidgin" aria-label="Permalink to “配置 Pidgin”">​</a></h3><p>首次啓動 Pidgin 時，點擊 “Add” 添加一個新帳户。在基本選項卡（如下截圖所示）中，選擇 “Protocol” 下拉菜單中的 “Office Communicator”，然後在 “Username” 字段中輸入你的“公司電子郵件地址”。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/pidgin_basic_account_screen_final.png?itok=1zoSbZjy" alt=""></p><p>接下來，點擊高級選項卡。在 “Server[:Port]” 字段中輸入 “sipdir.online.lync.com:443”，在 “User Agent” 中輸入 “UCCAPI/16.0.6965.5308 OC/16.0.6965.2117”。</p><p>你的高級選項卡現在應該如下所示：</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/pidgin_advanced_account_screen.png?itok=Z6loRfGi" alt=""></p><p>你不需要對“Proxy”選項卡或“Voice and Video”選項卡進行任何更改。只要確定，請確保 “Proxy type” 設置為 “Use Global Proxy Settings”，並且在“Voice and Video”選項卡中，“Use silence suppression” 複選框為<strong>取消選中</strong>。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/pidgin_account_proxy_screen.png?itok=iDgszWy0" alt=""></p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/pidgin_voiceandvideo_screen.png?itok=klkbt5hr" alt=""></p><p>完成這些配置後，點擊 “Add”，系統會提示你輸入電子郵件帳户的密碼。</p><h3 id="添加聯繫人" tabindex="-1">添加聯繫人 <a class="header-anchor" href="#添加聯繫人" aria-label="Permalink to “添加聯繫人”">​</a></h3><p>要將聯繫人添加到好友列表，請點擊<strong>好友窗口</strong>中的 “Manage Accounts”。將鼠標懸停在你的帳户上，然後選擇 “Contact Search” 查找你的同事。如果您在使用姓氏和名字進行搜索時遇到任何問題，請嘗試使用你同事的完整電子郵件地址進行搜索，你就會找到正確的人。</p><p>你現在已經開始使用 Skype for Business 替代產品，該產品可為你提供 98％ 的功能，從你的桌面上消除專有軟件。</p><hr>',15)),o("p",null,[e[15]||(e[15]=i("via: ",-1)),t(s,{href:"https://opensource.com/article/18/4/pidgin-open-source-replacement-skype-business"},{default:n(()=>[...e[14]||(e[14]=[i("https://opensource.com/article/18/4/pidgin-open-source-replacement-skype-business",-1)])]),_:1})]),o("p",null,[e[20]||(e[20]=i("作者：",-1)),t(s,{href:"https://opensource.com/users/shickmo"},{default:n(()=>[...e[16]||(e[16]=[i("Ray Shimko",-1)])]),_:1}),e[21]||(e[21]=i(" 選題：",-1)),t(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[17]||(e[17]=[i("lujun9972",-1)])]),_:1}),e[22]||(e[22]=i(" 譯者：",-1)),t(s,{href:"https://github.com/geekpi"},{default:n(()=>[...e[18]||(e[18]=[i("geekpi",-1)])]),_:1}),e[23]||(e[23]=i(" 校對：",-1)),t(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[19]||(e[19]=[i("wxy",-1)])]),_:1})]),o("p",null,[e[26]||(e[26]=i("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[24]||(e[24]=[i("LCTT",-1)])]),_:1}),e[27]||(e[27]=i(" 原創編譯，",-1)),t(s,{href:"https://linux.cn/"},{default:n(()=>[...e[25]||(e[25]=[i("Linux中國",-1)])]),_:1}),e[28]||(e[28]=i(" 榮譽推出",-1))])])}const x=r(a,[["render",f]]);export{b as __pageData,x as default};
